mapper.select:
SELECT s.id, s.user_id, u.real_name AS nick_name, u.avatar, s.session_name, s.agent_code, s.status, s.pinned, s.pinned_time, COALESCE(r.message_count, 0) AS message_count, COALESCE(r.token_usage, 0) AS token_usage, s.create_time, s.update_time FROM ai_chat_session s LEFT JOIN sys_user u ON s.user_id = u.id AND u.del_flag = 0 LEFT JOIN ( SELECT session_id, COUNT(*) AS message_count, COALESCE(SUM(token_usage), 0) AS token_usage FROM ai_chat_record WHERE del_flag = 0 GROUP BY session_id ) r ON r.session_id = s.id
1=1 AND s.status = '0'
AND (u.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR s.session_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND s.create_time >= #{query.startTime}
AND s.create_time <= CONCAT(#{query.endTime}, ' 23:59:59')
AND s.status = #{query.status}
AND s.agent_code = #{query.agentCode}
AND s.user_id = #{query.userId}
ORDER BY s.pinned DESC, s.pinned_time DESC, s.update_time DESC
